UPDATE t_p79235343_uplink_clone_website.cms_service_faq SET question = 'Как долго длится подключение сервера к обслуживанию?', answer = 'Первичное подключение занимает от 1 до 3 рабочих дней: диагностика, настройка мониторинга, документирование конфигурации. Экстренную поддержку подключаем в течение нескольких часов.' WHERE id = 4;

UPDATE t_p79235343_uplink_clone_website.cms_service_faq SET question = 'Что входит в мониторинг серверов?', answer = 'Отслеживание загрузки CPU, памяти, дискового пространства, температуры, состояния RAID, времени отклика сервисов. При выходе показателей за допустимые пределы инженер оперативно устраняет проблему.' WHERE id = 16;